const leadForm=document.querySelector('#lead-form');if(leadForm){leadForm.addEventListener('submit',async e=>{e.preventDefault();const status=leadForm.querySelector('[role=status]'),button=leadForm.querySelector('button');status.textContent='Đang gửi thông tin…';button.disabled=true;try{const payload=Object.fromEntries(new FormData(leadForm));const r=await fetch('/api/leads',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error||'Không thể gửi thông tin');leadForm.reset();status.textContent='Đăng ký thành công. Đội ngũ tư vấn sẽ liên hệ với bạn sớm.'}catch(err){status.textContent=err.message||'Có lỗi xảy ra. Vui lòng thử lại.'}finally{button.disabled=false}})}
